public static class RenderApiV1
{
    [Obsolete("Use IDocumentWriter; build the document model then call Write - no direct equivalent", false)]
    public static byte[] ToPdf(string title, IEnumerable<string> lines)
    {
        var text = title + "\n" + string.Join("\n", lines);
        return Encoding.UTF8.GetBytes(text);
    }
}

/// <summary>Builder-style document writer that replaces the single-call renderer.</summary>
public interface IDocumentWriter
{
    void AddTitle(string title);

    void AddLine(string line);

    byte[] Write();
}

/// <summary>Minimal in-memory <see cref="IDocumentWriter"/>.</summary>
public sealed class SimpleDocumentWriter : IDocumentWriter
{
    private readonly StringBuilder _builder = new();

    public void AddTitle(string title) => _builder.AppendLine("# " + title);

    public void AddLine(string line) => _builder.AppendLine(line);

    public byte[] Write() => Encoding.UTF8.GetBytes(_builder.ToString());
}
